import jax
import jax.numpy as jnp
import flax.linen as nn
import optax
from typing import Tuple, Optional, Dict
import pickle

# --- SELF-CONTAINED SUBMISSION ---
# All necessary components are inlined for robustness.

# ===== Cells =====
class ConvLSTMCellLN(nn.Module):
    features: int; kernel_size: Tuple[int,int] = (3,3)
    @nn.compact
    def __call__(self, carry, x):
        h, c = carry
        gates = nn.Conv(4*self.features, self.kernel_size, padding='SAME')(jnp.concatenate([x, h], axis=-1))
        gates = nn.LayerNorm(epsilon=1e-5)(gates)
        i,f,g,o = jnp.split(gates, 4, axis=-1); i=nn.sigmoid(i);f=nn.sigmoid(f);o=nn.sigmoid(o);g=jnp.tanh(g)
        c = f*c+i*g; h = o*jnp.tanh(c); return (h,c),h

class ConvLSTMCellNoLN(nn.Module):
    features: int; kernel_size: Tuple[int,int] = (3,3)
    @nn.compact
    def __call__(self, carry, x):
        h, c = carry
        gates = nn.Conv(4*self.features, self.kernel_size, padding='SAME')(jnp.concatenate([x, h], axis=-1))
        i,f,g,o = jnp.split(gates, 4, axis=-1); i=nn.sigmoid(i);f=nn.sigmoid(f);o=nn.sigmoid(o);g=jnp.tanh(g)
        c = f*c+i*g; h = o*jnp.tanh(c); return (h,c),h

# ===== Bottleneck Block =====
class BottleneckBlock(nn.Module):
    features: int
    @nn.compact
    def __call__(self, x):
        y = nn.Conv(self.features//4, (1,1))(x); y=nn.relu(y)
        y = nn.Conv(self.features//4, (3,3), padding='SAME')(y); y=nn.relu(y)
        y = nn.Conv(self.features, (1,1))(y); return nn.relu(x+y)

# ===== Probe Network =====
class KronoNetV4_Probe(nn.Module):
    cnn_features_1: int; cnn_features_2: int; conv_lstm_features: int; dilation_rate: int
    num_heads: int=2; steps: int=2; use_input_ln: bool=False; use_gate_ln: bool=True
    @nn.compact
    def __call__(self, x: jnp.ndarray, done: Optional[jnp.ndarray], rnn_state=None) -> Dict[str, jnp.ndarray]:
        B,H,W,_ = x.shape
        cnn_out = nn.Conv(self.cnn_features_1,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(x); cnn_out=nn.relu(cnn_out)
        cnn_out = BottleneckBlock(self.cnn_features_1)(cnn_out)
        cnn_out = nn.Conv(self.cnn_features_2,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(cnn_out); cnn_out=nn.relu(cnn_out)
        s1_raw_cnn = BottleneckBlock(self.cnn_features_2)(cnn_out)

        s2_normed_cnn = s1_raw_cnn
        if self.use_input_ln:
            s2_normed_cnn = nn.LayerNorm(name="convlstm_input_layernorm")(s1_raw_cnn)

        if rnn_state is None: rnn_state = (jnp.zeros((B,H,W,self.conv_lstm_features)), jnp.zeros((B,H,W,self.conv_lstm_features)))
        if done is not None: m=(1.0-done.reshape(B,1,1,1)); rnn_state=jax.tree.map(lambda y:y*m, rnn_state)

        h, c = rnn_state
        lstm_cell = ConvLSTMCellLN(self.conv_lstm_features) if self.use_gate_ln else ConvLSTMCellNoLN(self.conv_lstm_features)
        for _ in range(self.steps): (h,c), h_out = lstm_cell((h,c), s2_normed_cnn)
        s3_recurrent = h_out

        return {'s1_raw_cnn':s1_raw_cnn, 's2_normed_cnn':s2_normed_cnn, 's3_recurrent':s3_recurrent}

# ===== Test Function =====
def test():
    # Note: this file path is a guess based on how the system stores params. May need adjustment.
    param_path = 'storage/shared/results/776/best_trial/params.pkl'
    try:
        with open(param_path, 'rb') as f:
            params = pickle.load(f)
    except FileNotFoundError:
        return f"ERROR: Could not find params.pkl at {param_path}. Cannot run probe."

    key = jax.random.PRNGKey(42)
    batch_size = 128
    dummy_obs = jax.random.normal(key, (batch_size, 8, 8, 8))
    dummy_done = jnp.zeros(batch_size, dtype=bool)

    hparams = {
        'cnn_features_1': 32, 'cnn_features_2': 64, 'conv_lstm_features': 96,
        'dilation_rate': 6, 'num_heads': 2, 'steps': 2
    }

    configs = {
        "No LN":        {'use_input_ln': False, 'use_gate_ln': False},
        "Internal LN":  {'use_input_ln': False, 'use_gate_ln': True},
        "External LN":  {'use_input_ln': True,  'use_gate_ln': False},
        "Both LNs":     {'use_input_ln': True,  'use_gate_ln': True},
    }

    print("--- Feature Variance Probe ---")
    results = {}
    for name, config in configs.items():
        network = KronoNetV4_Probe(**hparams, **config)

        @jit
        def run_probe(p, obs, done):
            return network.apply(p, obs, done)

        features = run_probe(params, dummy_obs, dummy_done)

        variances = {k: jnp.mean(jnp.var(v, axis=0)) for k, v in features.items()}
        results[name] = variances
        print(f"[{name}]")
        print(f"  - s1_raw_cnn:   {variances['s1_raw_cnn']:.6f}")
        print(f"  - s2_normed_cnn:{variances['s2_normed_cnn']:.6f}")
        print(f"  - s3_recurrent: {variances['s3_recurrent']:.6f}")

    return "Probe complete. Results printed to STDOUT."
